<?php
 namespace QQWorld\Customer\CustomerData; class SectionConfigConverter implements \QQWorld\Framework\Config\ConverterInterface { const INVALIDATE_ALL_SECTIONS_MARKER = '*'; public function convert($source) { $sections = []; foreach ($source->getElementsByTagName('action') as $action) { $actionName = strtolower($action->getAttribute('name')); foreach ($action->getElementsByTagName('section') as $section) { $sections[$actionName][] = strtolower($section->getAttribute('name')); } if (!isset($sections[$actionName])) { $sections[$actionName] = self::INVALIDATE_ALL_SECTIONS_MARKER; } } return [ 'sections' => $sections, ]; } } 